"""Console-oriented patient check-in component with replaceable I/O.

The console holds one public ``session`` dictionary, interprets structured
check-in actions via ``handle``, and emits deterministic screen dictionaries
(``prompt``, ``messages``, ``choices``).  Input acquisition and output display
are duck-typed collaborators (``read_action()`` / ``display(screen)``) so
unittest fakes from the standard library can replace them directly.
"""

_INITIAL_SESSION = {
    "active": False,
    "contact_confirmed": None,
    "appointment_id": None,
    "completed": False,
}


class CheckInConsole:
    def __init__(self, appointments, action_source=None, screen_sink=None):
        self._appointments = [
            {"id": a["id"], "label": a["label"]} for a in appointments
        ]
        self._appointment_ids = {a["id"] for a in self._appointments}
        self.action_source = action_source
        self.screen_sink = screen_sink
        self.session = dict(_INITIAL_SESSION)

    # -- screen construction -------------------------------------------------

    def _screen(self, prompt, messages=None):
        if prompt == "Choose appointment":
            choices = [dict(a) for a in self._appointments]
        else:
            choices = []
        return {
            "prompt": prompt,
            "messages": list(messages) if messages else [],
            "choices": choices,
        }

    def _next_prompt(self):
        if self.session["contact_confirmed"] is not True:
            return "Confirm contact"
        if self.session["appointment_id"] is None:
            return "Choose appointment"
        return "Review and complete"

    def _current_prompt(self):
        if self.session["completed"]:
            return "Check-in complete"
        if not self.session["active"]:
            return "Begin check-in"
        return self._next_prompt()

    def _error(self, reason):
        return self._screen(self._current_prompt(), ["Error: " + reason])

    # -- validation guards ---------------------------------------------------

    def _require_in_progress(self):
        if not self.session["active"] or self.session["completed"]:
            return self._error("no active check-in session")
        return None

    # -- action handlers -----------------------------------------------------

    def _handle_begin(self, action):
        if self.session["active"]:
            return self._error("a session is already active")
        self.session = dict(_INITIAL_SESSION)
        self.session["active"] = True
        return self._screen("Confirm contact")

    def _handle_confirm_contact(self, action):
        error = self._require_in_progress()
        if error is not None:
            return error
        confirmed = action.get("confirmed")
        if not isinstance(confirmed, bool):
            return self._error("'confirmed' must be a boolean")
        self.session["contact_confirmed"] = confirmed
        return self._screen(
            "Choose appointment" if confirmed else "Confirm contact"
        )

    def _handle_choose_appointment(self, action):
        error = self._require_in_progress()
        if error is not None:
            return error
        appointment_id = action.get("appointment_id")
        if appointment_id not in self._appointment_ids:
            return self._error("unknown appointment id")
        self.session["appointment_id"] = appointment_id
        return self._screen("Review and complete")

    def _handle_correct(self, action):
        error = self._require_in_progress()
        if error is not None:
            return error
        field = action.get("field")
        value = action.get("value")
        if field == "contact_confirmed":
            if not isinstance(value, bool):
                return self._error(
                    "correcting 'contact_confirmed' requires a boolean value"
                )
        elif field == "appointment_id":
            if value is not None and value not in self._appointment_ids:
                return self._error(
                    "correcting 'appointment_id' requires a known id or None"
                )
        else:
            return self._error("unknown correction field")
        self.session[field] = value
        return self._screen(self._next_prompt())

    def _handle_complete(self, action):
        error = self._require_in_progress()
        if error is not None:
            return error
        if self.session["contact_confirmed"] is not True:
            return self._error("contact must be confirmed before completing")
        if self.session["appointment_id"] is None:
            return self._error("an appointment must be chosen before completing")
        self.session["completed"] = True
        self.session["active"] = False
        return self._screen("Check-in complete", ["Checked in"])

    def _handle_abandon(self, action):
        if not self.session["active"]:
            return self._error("no active session to abandon")
        self.session = dict(_INITIAL_SESSION)
        return self._screen("Session abandoned", ["Check-in abandoned"])

    _HANDLERS = {
        "begin": _handle_begin,
        "confirm_contact": _handle_confirm_contact,
        "choose_appointment": _handle_choose_appointment,
        "correct": _handle_correct,
        "complete": _handle_complete,
        "abandon": _handle_abandon,
    }

    # -- public entry points -------------------------------------------------

    def handle(self, action):
        if not isinstance(action, dict):
            return self._error("action must be a dictionary")
        handler = self._HANDLERS.get(action.get("type"))
        if handler is None:
            return self._error("unknown action type")
        return handler(self, action)

    def run_once(self):
        if self.action_source is None or self.screen_sink is None:
            raise RuntimeError(
                "run_once requires both an action source and a screen sink"
            )
        screen = self.handle(self.action_source.read_action())
        self.screen_sink.display(screen)
        return screen
